fn reverse_upto_k(s: &mut Vec<i32>, k: usize) {
    // We reverse the first k elements of the array in place.
    // Since k ≥ 2 and k ≤ s.len(), no empty or invalid slice issues arise.

    let mut left = 0;
    let mut right = k - 1;

    while left < right {
        s.swap(left, right);
        left += 1;
        right -= 1;
    }
}